package com.example.myproject.data.local.dao.model

import androidx.room.ColumnInfo

data class PlanDetailQueryModel(
    val planId: String,
    val userId: String,
    val title: String,
    val status: Int,
    val isPreset: Boolean,
    val totalWeeks: Int,
    @ColumnInfo(name = "daily_minutes")
    val dailyMinutes: Int,
    @ColumnInfo(name = "completed_days")
    val completedDays: Int,
    @ColumnInfo(name = "action_count")
    val actionCount: Int,
    @ColumnInfo(name = "today_completed_groups")
    val todayCompletedGroups: Int?,
    @ColumnInfo(name = "today_total_groups")
    val todayTotalGroups: Int?
)

package com.example.myproject.data.local

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import com.example.myproject.data.local.dao.PlanDao
import com.example.myproject.data.local.entity.ActionEntity
import com.example.myproject.data.local.entity.ActionStepEntity
import com.example.myproject.data.local.entity.PlanActionEntity
import com.example.myproject.data.local.entity.PlanEntity
import com.example.myproject.data.local.entity.TrainingLogEntity

@Database(
    entities = [
        //UserEntity::class,
        PlanEntity::class,
        ActionEntity::class,
        ActionStepEntity::class,
        PlanActionEntity::class,
        TrainingLogEntity::class
    ],
    version = 1,
    exportSchema = true   // 导出 schema 到 JSON，便于后续 Migration 追踪
)
abstract class AppDatabase : RoomDatabase() {

    //abstract fun userDao(): UserDao
    abstract fun planDao(): PlanDao
//    abstract fun actionDao(): ActionDao
//    abstract fun actionStepDao(): ActionStepDao
//    abstract fun planActionDao(): PlanActionDao
//    abstract fun trainingLogDao(): TrainingLogDao

    companion object {
        private const val DB_NAME = "MyDatabase.db"

        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getInstance(context: Context): AppDatabase =
            INSTANCE ?: synchronized(this) {
                INSTANCE ?: Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    DB_NAME
                )
                    .build()
                    .also { INSTANCE = it }
            }
    }
}

package com.example.myproject.data.local

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import com.example.myproject.data.local.dao.PlanDao
import com.example.myproject.data.local.entity.ActionEntity
import com.example.myproject.data.local.entity.ActionStepEntity
import com.example.myproject.data.local.entity.PlanActionEntity
import com.example.myproject.data.local.entity.PlanEntity
import com.example.myproject.data.local.entity.TrainingLogEntity

@Database(
    entities = [
        //UserEntity::class,
        PlanEntity::class,
        ActionEntity::class,
        ActionStepEntity::class,
        PlanActionEntity::class,
        TrainingLogEntity::class
    ],
    version = 1,
    exportSchema = true   // 导出 schema 到 JSON，便于后续 Migration 追踪
)
abstract class AppDatabase : RoomDatabase() {

    //abstract fun userDao(): UserDao
    abstract fun planDao(): PlanDao
//    abstract fun actionDao(): ActionDao
//    abstract fun actionStepDao(): ActionStepDao
//    abstract fun planActionDao(): PlanActionDao
//    abstract fun trainingLogDao(): TrainingLogDao

    companion object {
        private const val DB_NAME = "MyDatabase.db"

        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getInstance(context: Context): AppDatabase =
            INSTANCE ?: synchronized(this) {
                val dbBuilder = Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    DB_NAME
                )
                // 取消下面注释即可在首次创建数据库时注入初始数据
                // dbBuilder.addCallback(DatabaseSeeder { INSTANCE!! })
                INSTANCE ?: dbBuilder
                    .build()
                    .also { INSTANCE = it }
            }
    }
}
